"""Prepare actual fixed-event probes on the existing audited private projects."""
from pathlib import Path
import json,re
root=Path(__file__).resolve().parent.parent;home=root/'artifacts/fixed-update-check';home.mkdir(exist_ok=True)
unity=root/'artifacts/runtime-ui-api-tests/UnitySource';core=Path(json.loads((root/'artifacts/core-engine-launch-tests/paths.json').read_text())['run'])
folder=unity/'Assets/EngineMigratorFixedProbe';(folder/'Editor').mkdir(parents=True,exist_ok=True)
source=(root/'tests/EngineMigrator.Checks/Fixtures/fixed-update.cs.txt').read_text()
names=re.findall(r'public class (\w+)',source)
for match in re.finditer(r'public class (\w+)',source):
 start=match.start();brace=source.index('{',start);level=1;end=brace+1
 while level:
  level+=(source[end]=='{')-(source[end]=='}');end+=1
 (folder/(match.group(1)+'.cs')).write_text('using UnityEngine;\n'+source[start:end])
restored=home/'restored'
if restored.exists():
 for path in restored.glob('*.cs'):
  text=path.read_text()
  for name in sorted(names,key=len,reverse=True):text=re.sub(r'\b'+name+r'\b','Restored'+name,text)
  (folder/('Restored'+path.name)).write_text(text)
editor='''using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public class EMFixedObserver:MonoBehaviour{
 public Component controller;public Component worker;public Component ledger;public float step;public int fps;private int prior;private List<string> rows=new List<string>();private List<string> clockRows=new List<string>();
 void Awake(){Time.captureDeltaTime=1f/fps;Time.fixedDeltaTime=step;}
 void Start(){Time.captureDeltaTime=1f/fps;Time.fixedDeltaTime=step;}
 void LateUpdate(){try{int frame=(int)controller.GetType().GetField("Frame").GetValue(controller);if(frame==prior)return;prior=frame;var row=new List<string>{frame.ToString(),Time.deltaTime.ToString("R",System.Globalization.CultureInfo.InvariantCulture)};foreach(var name in new[]{"AwakeCount","EnableCount","DisableCount","StartCount","FixedCount","DerivedFixed","Updates","FixedElapsed","LastDelta","StepSeen","StartedBeforeFixed"}){object value=worker.GetType().GetField(name).GetValue(worker);row.Add(value is bool b?(b?"1":"0"):Convert.ToString(value,System.Globalization.CultureInfo.InvariantCulture));}foreach(var name in new[]{"Code","Calls","AddedFixed"})row.Add(Convert.ToString(ledger.GetType().GetField(name).GetValue(ledger),System.Globalization.CultureInfo.InvariantCulture));rows.Add("["+string.Join(",",row)+"]");var ct=Time.timeAsRational;var dt=Time.captureDeltaTimeRational;clockRows.Add("["+ct.Count+","+ct.Ticks.Numerator+","+ct.Ticks.Denominator+","+Time.timeAsDouble.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+","+Time.fixedTimeAsDouble.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+","+dt.Count+","+Time.fixedDeltaTime.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+"]");Time.captureDeltaTime=1f/fps;if(frame>=24){File.WriteAllText(Environment.GetEnvironmentVariable("EM_FIXED_OUTPUT")+".clock.json","["+string.Join(",",clockRows)+"]");File.WriteAllText(Environment.GetEnvironmentVariable("EM_FIXED_OUTPUT"),"{\\"status\\":\\"CAPTURED\\",\\"rows\\":["+string.Join(",",rows)+"]}");EditorApplication.Exit(0);}}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
}
public static class EMFixedProbe{public static void Run(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);bool restored=Environment.GetEnvironmentVariable("EM_FIXED_RESTORED")=="1";string prefix=restored?"Restored":"";var asm=typeof(FixedController).Assembly;var ledgerType=asm.GetType(prefix+"FixedLedger");var workerType=asm.GetType(prefix+"FixedWorker");var controllerType=asm.GetType(prefix+"FixedController");var ledger=new GameObject("Fixed ledger").AddComponent(ledgerType);var owner=new GameObject("Fixed owner");var worker=owner.AddComponent(workerType);var controller=new GameObject("Fixed controller").AddComponent(controllerType);workerType.GetField("Ledger").SetValue(worker,ledger);controllerType.GetField("Ledger").SetValue(controller,ledger);controllerType.GetField("Worker").SetValue(controller,worker);controllerType.GetField("Owner").SetValue(controller,owner);MonoImporter.SetExecutionOrder(MonoScript.FromMonoBehaviour((MonoBehaviour)controller),-100);MonoImporter.SetExecutionOrder(MonoScript.FromMonoBehaviour((MonoBehaviour)ledger),-200);var observer=new GameObject("Fixed observer").AddComponent<EMFixedObserver>();observer.controller=controller;observer.worker=worker;observer.ledger=ledger;observer.fps=int.Parse(Environment.GetEnvironmentVariable("EM_FIXED_FPS"));observer.step=float.Parse(Environment.GetEnvironmentVariable("EM_FIXED_STEP"),System.Globalization.CultureInfo.InvariantCulture);Time.captureDeltaTime=1f/observer.fps;Time.fixedDeltaTime=observer.step;EditorSettings.enterPlayModeOptionsEnabled=true;EditorSettings.enterPlayModeOptions=EnterPlayModeOptions.DisableDomainReload|EnterPlayModeOptions.DisableSceneReload;var deadline=EditorApplication.timeSinceStartup+120;EditorApplication.update+=()=>{if(EditorApplication.timeSinceStartup>deadline)EditorApplication.Exit(2);};EditorApplication.EnterPlaymode();}}
'''
(folder/'Editor/EMFixedProbe.cs').write_text(editor)
runner=home/'runner';runner.mkdir(exist_ok=True);(runner/'Runner.csproj').write_bytes((root/'artifacts/ui-equality-check/destruction-runner/Runner.csproj').read_bytes())
code='''using EngineMigrator.Core;using System.Text.Json;
var home=HOME;var unity=UNITY;var core=CORE;string Hash(string p)=>Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(p)));
Dictionary<string,string> Files()=>Directory.GetFiles(Path.Combine(core,"Project/Source"),"*",SearchOption.AllDirectories).Concat(Directory.GetFiles(Path.Combine(core,"Project/Plugins/EMActorPort/Source"),"*",SearchOption.AllDirectories)).Where(p=>new[]{".h",".cpp",".cs"}.Contains(Path.GetExtension(p))).Concat(new[]{Path.Combine(core,"Project/Binaries/Win64/UnrealEditor-EMPortHost.dll"),Path.Combine(core,"Project/Plugins/EMActorPort/Binaries/Win64/UnrealEditor-EMActorPort.dll")}).ToDictionary(p=>p,Hash);
if(args.Length!=1)throw new ArgumentException("Explicit mode required");var descriptor=Path.Combine(core,"Project/RuntimeWorld.uproject");var manifest=Path.Combine(home,"build-hashes.json");
if(args[0]=="prepare"){var files=ActorScripts.FromUnity(File.ReadAllText("tests/EngineMigrator.Checks/Fixtures/fixed-update.cs.txt"));foreach(var file in files){File.WriteAllText(Path.Combine(home,file.Name),file.Code);File.WriteAllText(Path.Combine(core,"Project/Plugins/EMActorPort/Source/EMActorPort/Public",file.Name),file.Code);}Directory.CreateDirectory(Path.Combine(home,"restored"));foreach(var file in ActorScripts.ToUnity(files))File.WriteAllText(Path.Combine(home,"restored",file.Name),file.Code);File.WriteAllText(Path.Combine(core,"Project/Source/EMPortHost/EMPortHost.cpp"),File.ReadAllText("artifacts/ui-equality-check/core-host-before-ui-destruction.cpp.txt")+File.ReadAllText("tools/fixed-update-game-observer.cpp.txt"));return;}
if(args[0]=="build"){using var timeout=new CancellationTokenSource(TimeSpan.FromMinutes(10));await ResourcePorting.RunEditor(EngineLaunchSafety.Dotnet,[EngineLaunchSafety.Ubt,"RuntimeWorldEditor","Win64","Development","-Project="+descriptor,"-NoHotReload","-NoPCH","-NoSharedPCH","-log="+Path.Combine(home,"build.log")],core,timeout.Token);File.WriteAllText(manifest,JsonSerializer.Serialize(Files()));return;}
var parts=args[0].Split('-');if(parts.Length!=3)throw new ArgumentException("mode-fps-stepMilliseconds required");var mode=parts[0];int fps=int.Parse(parts[1]);float step=int.Parse(parts[2])/1000f;var output=Path.Combine(home,args[0]+".json");var log=Path.Combine(home,args[0]+".log");if(File.Exists(output))throw new IOException("Fresh capture required");
if(mode is "original" or "restored"){var settings=Path.Combine(unity,"ProjectSettings/EditorSettings.asset");var before=File.ReadAllBytes(settings);var timeSettings=Path.Combine(unity,"ProjectSettings/TimeManager.asset");var beforeTime=File.ReadAllBytes(timeSettings);var keys=new[]{"EM_FIXED_OUTPUT","EM_FIXED_RESTORED","EM_FIXED_FPS","EM_FIXED_STEP"};var old=keys.Select(Environment.GetEnvironmentVariable).ToArray();var values=new[]{output,mode=="restored"?"1":"0",fps.ToString(),step.ToString("R",System.Globalization.CultureInfo.InvariantCulture)};for(int i=0;i<keys.Length;i++)Environment.SetEnvironmentVariable(keys[i],values[i]);try{using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(180));await ResourcePorting.RunEditor(EngineLaunchSafety.Unity,["-batchmode","-nographics","-projectPath",unity,"-executeMethod","EMFixedProbe.Run","-logFile",log],Directory.GetParent(unity)!.FullName,timeout.Token);if(!File.Exists(output))throw new IOException("Unity fixed capture missing");}finally{File.WriteAllBytes(settings,before);File.WriteAllBytes(timeSettings,beforeTime);for(int i=0;i<keys.Length;i++)Environment.SetEnvironmentVariable(keys[i],old[i]);}return;}
if(mode=="native"){var built=JsonSerializer.Deserialize<Dictionary<string,string>>(File.ReadAllText(manifest))!;var current=Files();if(built.Count!=current.Count||built.Any(p=>!current.TryGetValue(p.Key,out var hash)||hash!=p.Value))throw new IOException("Native source/binary build mismatch");using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(180));await ResourcePorting.RunEditor(EngineLaunchSafety.Unreal,[descriptor,"/Engine/Maps/Entry","-game","-nullrhi","-RenderOffscreen","-nosound","-unattended","-nop4","-nosplash","-UseFixedTimeStep","-FPS="+fps,"-EMFixedProbe="+output,"-EMFixedStep="+step.ToString("R",System.Globalization.CultureInfo.InvariantCulture),"-abslog="+log],core,timeout.Token);if(!File.Exists(output))throw new IOException("Native fixed capture missing");return;}
throw new ArgumentException("Unknown mode");
'''
